#include "InheritedBase.inc"
int main(int argc,char**argv){try{
 if(argc!=4)throw std::invalid_argument("SDK SCENE FRAME_PLUGIN");sofa::simulation::graph::init();sofa::simpleapi::init();sofa::helper::system::PluginRepository.addFirstPath(std::string(argv[1])+"/lib");sofa::simulation::Simulation::theSimulation=sofa::simpleapi::createSimulation("DAG");if(!sofa::simpleapi::importPlugin(argv[3]))throw std::runtime_error("plugin");auto root=sofa::simulation::node::load(argv[2]);if(!root)throw std::runtime_error("load");sofa::simulation::node::initRoot(root.get());auto*body=root->getChild("Multilayer");auto*state=dynamic_cast<State*>(body->getMechanicalState());Beam*beam=nullptr;for(auto*ff:static_cast<sofa::core::objectmodel::BaseContext*>(body)->getObjects<FF>(sofa::core::objectmodel::BaseContext::Local))if(auto*b=dynamic_cast<Beam*>(ff))beam=b;if(!state||!beam)throw std::runtime_error("beam/state");auto rest=state->read(sofa::core::vec_id::read_access::restPosition)->getValue();auto edges=body->getMeshTopology()->getEdges();std::cout<<std::setprecision(17);
 for(double amplitude:{.001,.1,.4})for(double rotate:{0.,1.7}){
  auto x=rest;auto rigid=sofa::type::Quat<double>(sofa::type::Vec3d(1,0,0),rotate);
  for(size_t i=0;i<x.size();++i){double s=rest[i].getCenter()[0]/100;x[i].getCenter()[2]+=amplitude*s*s;x[i].getOrientation()=sofa::type::Quat<double>(sofa::type::Vec3d(0,1,0),-2*amplitude*s/100.)*rest[i].getOrientation();x[i].getCenter()=rigid.rotate(x[i].getCenter())+sofa::type::Vec3d(2,3,4);x[i].getOrientation()=rigid*x[i].getOrientation();}
  FF::DataVecCoord xd;xd.setValue(x);FF::DataVecDeriv f,v;f.setValue(Types::VecDeriv(x.size()));v.setValue(Types::VecDeriv(x.size()));sofa::core::MechanicalParams mp;beam->addForce(&mp,f,xd,v);sofa::type::Vec3d netF{},netM{},prediction{};for(size_t i=0;i<x.size();++i){auto a=f.getValue()[i].getVCenter(),t=f.getValue()[i].getVOrientation();netF+=a;netM+=t+cross(x[i].getCenter()-x[0].getCenter(),a);}
  for(size_t i=0;i<edges.size();++i){unsigned a=edges[i][0],b=edges[i][1];auto base=rest[a].getOrientation().inverseRotate(rest[b].getCenter()-rest[a].getCenter());auto u=x[a].getOrientation().inverseRotate(x[b].getCenter()-x[a].getCenter())-base;auto q0=rest[a].getOrientation().inverse()*rest[b].getOrientation(),q=x[a].getOrientation().inverse()*x[b].getOrientation();auto dq=q0.inverse()*q;dq.normalize();if(dq[3]<0)for(int j=0;j<4;++j)dq[j]=-dq[j];auto theta=dq.quatToRotationVector();Beam::Displacement d;d.clear();for(int j=0;j<3;++j){d[j+6]=u[j];d[j+9]=theta[j];}auto local=beam->d_beamsData.getValue()[i]._k_loc*d;auto fb=x[a].getOrientation().rotate(sofa::type::Vec3d(-local[6],-local[7],-local[8]));prediction+=cross(x[a].getOrientation().rotate(u),fb);}
  std::cout<<"INHERITED {\"amplitude\":"<<amplitude<<",\"rigid_rotation\":"<<rotate<<",\"net_force\":["<<netF[0]<<','<<netF[1]<<','<<netF[2]<<"],\"net_moment\":["<<netM[0]<<','<<netM[1]<<','<<netM[2]<<"],\"missing_geometric_couple_prediction\":["<<prediction[0]<<','<<prediction[1]<<','<<prediction[2]<<"],\"prediction_error\":"<<(netM-prediction).norm()<<"}"<<std::endl;
 }
 sofa::simulation::node::unload(root);root.reset();sofa::simulation::Simulation::theSimulation.reset();sofa::simpleapi::cleanup();sofa::simulation::graph::cleanup();return 0;
}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<std::endl;return 1;}}
